Item.method_code:
const itemNode =
	aras.itemsCache.getItem(itemId) ||
	aras.itemsCache.getItemByXPath(
		`Innovator/Items/Item/Relationships/Item[@id="${itemId}"]`
	);

const currentValue = aras.getItemProperty(itemNode, 'prop_source');
if (!currentValue) {
	return;
}

aras.setItemProperty(itemNode, 'prop_source', '');
